const state={customer:localStorage.getItem("ipa_customer")||"prospect",route:"home",plannerStep:0,live:false,liveSeconds:0,messages:[{from:"Guia",text:"Bom dia, grupo! Nosso ponto de encontro é às 9h na recepção."},{from:"Ana",text:"Perfeito! Estamos animados 😍"}]};const screen=document.querySelector("#screen"),app=document.querySelector("#app"),splash=document.querySelector("#splash"),modal=document.querySelector("#modal");setTimeout(()=>{splash.classList.add("hidden");app.classList.remove("hidden");render()},1400);document.querySelectorAll(".bottom-nav button").forEach(btn=>{btn.addEventListener("click",()=>{state.route=btn.dataset.route;document.querySelectorAll(".bottom-nav button").forEach(b=>b.classList.toggle("active",b===btn));render()})});document.querySelector("#stateMenuBtn").onclick=()=>showStateMenu();function render(){if(state.customer==="prospect")return renderProspect();if(state.route==="home")return renderCustomerHome();if(state.route==="explore")return renderExplore();if(state.route==="trip")return renderTrip();if(state.route==="community")return renderCommunity();if(state.route==="profile")return renderProfile()}function renderProspect(){document.querySelector(".bottom-nav").style.display="none";if(state.plannerStep===0){screen.innerHTML=`<section class="premium-hero"><div class="hero-overlay"><small>INDO POR AÍ • COM A GENTE</small><h1>Sua próxima história começa aqui.</h1><p>Você sonha. A gente planeja, organiza e acompanha cada momento.</p><button class="cta" onclick="startPlanner()">Quero planejar minha viagem</button><button class="cta glass" onclick="becomeCustomer()">Já sou cliente</button></div></section><div class="section-title"><h2>Destinos para inspirar</h2><small>Explore</small></div><div class="destination-scroll"><button class="destination-card" style="background-image:url('assets/portugal.jpg')" onclick="startPlanner()"><span>Portugal</span><small>História, gastronomia e paisagens</small></button><button class="destination-card" style="background-image:url('assets/praia.jpg')" onclick="startPlanner()"><span>Praias</span><small>Descanso e experiências em família</small></button><button class="destination-card" style="background-image:url('assets/montanha.jpg')" onclick="startPlanner()"><span>Natureza</span><small>Roteiros que ficam na memória</small></button><button class="destination-card" style="background-image:url('assets/baloes.jpg')" onclick="startPlanner()"><span>Aventura</span><small>Momentos fora do comum</small></button></div><div class="section-title"><h2>Como funciona?</h2></div><div class="card journey-card"><div class="journey-step"><b>1</b><span><strong>Conte seu sonho</strong><small>Destino, datas e estilo de viagem</small></span></div><div class="journey-step"><b>2</b><span><strong>Receba sua proposta</strong><small>Roteiro completo e personalizado</small></span></div><div class="journey-step"><b>3</b><span><strong>Aprove e acompanhe</strong><small>Tudo organizado dentro do app</small></span></div><div class="journey-step"><b>4</b><span><strong>Viva a experiência</strong><small>Mapa, grupo, Live, fotos e memórias</small></span></div></div><div class="section-title"><h2>Por que viajar com a gente?</h2></div><div class="grid">${choice("🧠","Planejamento personalizado","Uma viagem com o seu ritmo")}${choice("💬","Concierge próximo","Suporte antes e durante")}${choice("🗺️","Tudo em um só lugar","Roteiro, mapas e documentos")}${choice("📸","Memórias para sempre","Fotos, álbum e filme da viagem")}</div><div class="brand-callout"><img src="data:image/png;base64," alt="Indo por Aí"><div><strong>@indo.por.ai.com.a.gente</strong><small>Acompanhe nossas aventuras</small></div></div>`}else renderPlanner()}function choice(e,t,x){return `<button class="card choice" onclick="startPlanner()"><span class="emoji">${e}</span><div><h3>${t}</h3><p>${x}</p></div></button>`}function line(i,t,x){return `<div class="timeline-item"><div class="dot">${i}</div><div><strong>${t}</strong><p>${x}</p></div></div>`}function startPlanner(){state.plannerStep=1;render()}function renderPlanner(){const s=[{title:"Para onde você sonha em ir?",body:`<div class="chips">${["Portugal","Disney","Japão","Itália","Chile","Outro"].map(x=>`<button class="chip" onclick="nextPlanner('${x}')">${x}</button>`).join("")}</div><div class="card" style="margin-top:16px"><label>Ou digite o destino</label><input id="destination" placeholder="Ex.: Porto e Lisboa"></div>`},{title:"Quando e com quem?",body:`<div class="form"><label>Mês da viagem<input type="month" value="2027-05"></label><label>Quantidade de viajantes<select><option>2 adultos</option><option>2 adultos e 1 criança</option><option>Grupo com 8 pessoas</option></select></label><button class="cta" onclick="nextPlanner()">Continuar</button></div>`},{title:"Qual estilo combina com você?",body:`<div class="grid">${["🍷 Gastronomia","🏖️ Praia","🏛️ História","🌿 Natureza","🎢 Parques","🚗 Road trip"].map(x=>`<button class="card choice" onclick="toggleChoice(this)"><span class="emoji">${x.split(" ")[0]}</span><strong>${x.substring(3)}</strong></button>`).join("")}</div><button class="cta" style="width:100%;margin-top:18px" onclick="nextPlanner()">Montar prévia</button>`},{title:"Sua primeira ideia de viagem",body:`<div class="card"><small>ROTEIRO SUGERIDO</small><h2>Portugal • 10 dias</h2><p>Porto → Vale do Douro → Coimbra → Lisboa</p><div class="progress"><span style="width:78%"></span></div><p style="margin-top:12px">Experiências gastronômicas, passeios em família, roteiro otimizado e concierge.</p><div class="price">R$ 18.900</div><small>estimativa inicial para 2 adultos</small></div><button class="cta" style="width:100%;margin-top:14px" onclick="showProposal()">Quero falar com o Indo por Aí</button><button class="cta secondary" style="width:100%;margin-top:10px" onclick="state.plannerStep=1;render()">Personalizar novamente</button>`}];const i=Math.min(state.plannerStep-1,s.length-1);screen.innerHTML=`<button class="chip" onclick="backPlanner()">← Voltar</button><div class="stepper">${s.map((_,j)=>`<span class="${j===i?'active':''}"></span>`).join("")}</div><h1>${s[i].title}</h1>${s[i].body}`}function nextPlanner(){state.plannerStep++;render()}function backPlanner(){state.plannerStep=Math.max(0,state.plannerStep-1);render()}function toggleChoice(el){el.style.outline=el.style.outline?"":"3px solid #F47A2A"}function showProposal(){modal.classList.remove("hidden");modal.innerHTML=`<div class="sheet"><h2>Recebemos seu sonho ✨</h2><p>Um especialista do Indo por Aí vai revisar sua prévia e continuar o atendimento.</p><div class="notice">Simulação: ao confirmar, o aplicativo desbloqueia a área de cliente.</div><button class="cta" style="width:100%;margin-top:16px" onclick="becomeCustomer()">Simular contratação</button><button class="chip" style="width:100%;margin-top:10px" onclick="closeModal()">Fechar</button></div>`}function becomeCustomer(){state.customer="customer";localStorage.setItem("ipa_customer","customer");state.route="home";state.plannerStep=0;closeModal();document.querySelector(".bottom-nav").style.display="grid";render()}function closeModal(){modal.classList.add("hidden");modal.innerHTML=""}function renderCustomerHome(){document.querySelector(".bottom-nav").style.display="grid";screen.innerHTML=`<div class="chips"><button class="chip" onclick="setTravelMode('before')">Antes</button><button class="chip" onclick="setTravelMode('during')">Durante</button><button class="chip" onclick="setTravelMode('after')">Depois</button></div><section class="hero" style="margin-top:12px"><small>OLÁ, RENATO 👋</small><h1>Portugal está chegando.</h1><p>Faltam 14 dias. Sua preparação está 72% concluída.</p><div class="progress"><span style="width:72%"></span></div><button class="cta secondary" style="margin-top:18px" onclick="state.route='trip';render()">Abrir minha viagem</button></section><div class="section-title"><h2>Próxima ação</h2><small>Hoje</small></div><div class="card">${line("🛂","Passaporte conferido","Tudo certo para os dois viajantes")}${line("📱","Comprar chip internacional","Recomendado até amanhã")}</div><div class="section-title"><h2>Atalhos</h2></div><div class="grid">${quick("🗺️","Roteiro","trip")}${quick("🔴","Modo Live","live")}${quick("📸","Álbum","album")}${quick("💬","Concierge","community")}</div>`}function quick(i,l,a){return `<button class="card choice" onclick="quickAction('${a}')"><span class="emoji">${i}</span><strong>${l}</strong></button>`}function quickAction(a){if(a==="live")return openLive();if(a==="album")return openAlbum();state.route=a;render()}function setTravelMode(m){if(m==="before"){state.route="trip";renderTrip()}if(m==="during")openLive();if(m==="after")openAlbum()}function renderTrip(){screen.innerHTML=`<section class="hero"><small>MINHA VIAGEM</small><h1>Portugal • 10 dias</h1><p>São Paulo → Porto → Lisboa</p><div class="progress"><span style="width:72%"></span></div></section><div class="section-title"><h2>Preparação</h2><small>72%</small></div><div class="card timeline">${service("✈️","Passagens","Emitidas","ok")}${service("🏨","Hotéis","Confirmados","ok")}${service("🛡️","Seguro viagem","Emitido","ok")}${service("🚐","Transfer","Aguardando confirmação","wait")}${service("📱","Chip internacional","Pendente","wait")}</div><div class="section-title"><h2>Seu roteiro</h2><small onclick="state.route='explore';render()">Ver mapa</small></div><div class="card timeline">${line("1","Torre dos Clérigos","09:00 • 1h")}${line("2","Livraria Lello","11:00 • ingresso no app")}${line("3","Almoço na Ribeira","13:00 • reserva confirmada")}${line("4","Cruzeiro no Douro","16:30 • ponto de encontro no mapa")}</div>`}function service(i,t,x,s){return `<div class="timeline-item"><div class="dot">${i}</div><div><strong>${t}</strong><p>${x}</p><span class="status ${s==='wait'?'wait':''}">${s==='wait'?'EM ANDAMENTO':'CONCLUÍDO'}</span></div></div>`}function renderExplore(){screen.innerHTML=`<h1>Mapa da viagem</h1><p>Veja o roteiro do dia e abra a navegação para cada ponto.</p><div class="map"><div class="pin" style="left:18%;top:22%"><span>1</span></div><div class="pin" style="left:60%;top:28%"><span>2</span></div><div class="pin" style="left:36%;top:63%"><span>3</span></div><div class="pin" style="left:72%;top:70%"><span>4</span></div></div><div class="card" style="margin-top:14px"><h3>Próximo ponto: Torre dos Clérigos</h3><p>09:00 • 12 min de caminhada</p><button class="cta" onclick="openMaps()">Ir agora</button></div><div class="section-title"><h2>Perto de você</h2></div><div class="chips"><button class="chip">🍝 Restaurantes</button><button class="chip">☕ Cafés</button><button class="chip">💊 Farmácias</button><button class="chip">🚇 Metrô</button></div>`}function openMaps(){window.open("https://www.google.com/maps/dir/?api=1&destination=Torre+dos+Clerigos+Porto","_blank")}function renderCommunity(){screen.innerHTML=`<div class="section-title"><h2>Grupo Portugal</h2><small onclick="openLive()">🔴 Entrar ao vivo</small></div><div class="notice">📢 Aviso fixado: encontro amanhã às 9h na recepção.</div><div class="chat" id="chat">${state.messages.map(m=>`<div class="msg ${m.from==='Você'?'me':''}"><strong>${m.from}</strong><br>${m.text}</div>`).join("")}</div><div class="chatbox"><input id="msgInput" placeholder="Escreva uma mensagem"><button class="cta" onclick="sendMessage()">Enviar</button></div>`}function sendMessage(){const i=document.querySelector("#msgInput");if(!i.value.trim())return;state.messages.push({from:"Você",text:i.value.trim()});renderCommunity()}let liveTimer,liveStream=null,liveFacingMode="environment",liveMicEnabled=true;async function openLive(){state.live=true;state.liveSeconds=0;modal.classList.remove("hidden");modal.innerHTML=`<div class="sheet live-sheet"><div class="live-card"><div class="live-video"><video id="liveVideo" autoplay playsinline muted></video><div id="liveFallback" class="live-fallback"><div class="camera-loader">📹</div><strong>Preparando câmera...</strong><small>Autorize câmera e microfone quando o celular solicitar.</small></div><span class="live-badge">● AO VIVO</span><span class="live-stats">👁 <span id="viewerCount">28</span> • <span id="timer">00:00</span></span><div class="live-caption"><strong>Renato • Porto</strong><br><small>Transmissão da viagem</small></div></div><div class="live-controls"><button id="micBtn" class="round-btn" onclick="toggleLiveMic()">🎤</button><button class="round-btn" onclick="switchLiveCamera()">🔄</button><button class="round-btn" onclick="shareLiveLocation()">📍</button><button class="round-btn" onclick="reactLive()">❤️</button><button class="round-btn danger" onclick="endLive()">■</button></div><div class="live-info"><p id="liveReaction">A câmera será exibida ao vivo neste aparelho.</p><div id="locationStatus"></div></div></div></div>`;clearInterval(liveTimer);liveTimer=setInterval(()=>{state.liveSeconds++;const t=document.querySelector("#timer");if(t){const m=String(Math.floor(state.liveSeconds/60)).padStart(2,"0"),s=String(state.liveSeconds%60).padStart(2,"0");t.textContent=`${m}:${s}`}},1000);await startLiveCamera()}async function startLiveCamera(){const v=document.querySelector("#liveVideo"),f=document.querySelector("#liveFallback");if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){if(f)f.innerHTML="<strong>Câmera não suportada.</strong><small>Abra pelo Safari e use HTTPS.</small>";return}try{if(liveStream)liveStream.getTracks().forEach(t=>t.stop());liveStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:liveFacingMode}},audio:true});if(v){v.srcObject=liveStream;await v.play().catch(()=>{})}if(f)f.classList.add("hidden");liveMicEnabled=true;updateMicButton()}catch(e){console.error(e);if(f){f.classList.remove("hidden");f.innerHTML="<strong>Não foi possível abrir a câmera.</strong><small>Verifique as permissões do Safari para câmera e microfone.</small>"}}}function toggleLiveMic(){if(!liveStream)return;liveMicEnabled=!liveMicEnabled;liveStream.getAudioTracks().forEach(t=>t.enabled=liveMicEnabled);updateMicButton();const r=document.querySelector("#liveReaction");if(r)r.textContent=liveMicEnabled?"🎤 Microfone ativado.":"🔇 Microfone silenciado."}function updateMicButton(){const b=document.querySelector("#micBtn");if(b)b.textContent=liveMicEnabled?"🎤":"🔇"}async function switchLiveCamera(){liveFacingMode=liveFacingMode==="environment"?"user":"environment";const r=document.querySelector("#liveReaction");if(r)r.textContent="🔄 Trocando câmera...";await startLiveCamera();if(r)r.textContent=liveFacingMode==="user"?"Câmera frontal ativada.":"Câmera traseira ativada."}function shareLiveLocation(){const s=document.querySelector("#locationStatus");if(!navigator.geolocation){if(s)s.innerHTML='<div class="notice">Localização não suportada.</div>';return}if(s)s.innerHTML='<div class="notice">Buscando localização...</div>';navigator.geolocation.getCurrentPosition(p=>{const a=p.coords.latitude.toFixed(5),b=p.coords.longitude.toFixed(5);if(s)s.innerHTML=`<div class="notice">📍 Localização compartilhada: ${a}, ${b}</div>`},()=>{if(s)s.innerHTML='<div class="notice">Confira a permissão de localização do Safari.</div>'},{enableHighAccuracy:true,timeout:10000})}function reactLive(){const r=document.querySelector("#liveReaction"),v=document.querySelector("#viewerCount");if(r)r.textContent="❤️ Você e mais 16 pessoas reagiram ao vivo.";if(v)v.textContent=String(Number(v.textContent||28)+1)}function endLive(){clearInterval(liveTimer);if(liveStream){liveStream.getTracks().forEach(t=>t.stop());liveStream=null}state.live=false;closeModal()}function openAlbum(){modal.classList.remove("hidden");modal.innerHTML=`<div class="sheet"><h2>Minha História • Portugal</h2><p>10 dias • 4 cidades • 342 fotos • 27 vídeos</p><div class="photo-grid">${["📷","🌉","🍷","🏰","🚋","🌅","🥘","⛵","❤️"].map(x=>`<div class="photo">${x}</div>`).join("")}</div><div class="card" style="margin-top:16px"><h3>🎬 Filme da viagem</h3><p>Uma prévia de 1 minuto com fotos, mapa e momentos favoritos.</p><button class="cta">Gerar filme</button></div><button class="chip" style="width:100%;margin-top:12px" onclick="closeModal()">Fechar</button></div>`}function renderProfile(){screen.innerHTML=`<div class="card" style="text-align:center"><div style="font-size:64px">👤</div><h2>Renato Ferreira</h2><p>Viajante Indo por Aí</p></div><div class="section-title"><h2>Passaporte digital</h2></div><div class="grid"><div class="card"><div class="emoji">🇧🇷</div><h3>Brasil</h3><p>12 viagens</p></div><div class="card"><div class="emoji">🇵🇹</div><h3>Portugal</h3><p>Próxima viagem</p></div><div class="card"><div class="emoji">🇮🇪</div><h3>Irlanda</h3><p>Memórias salvas</p></div><div class="card"><div class="emoji">＋</div><h3>Novo destino</h3><p>Planejar</p></div></div><button class="chip" style="width:100%;margin-top:18px" onclick="resetProspect()">Simular usuário não cliente</button>`}function resetProspect(){state.customer="prospect";localStorage.setItem("ipa_customer","prospect");state.plannerStep=0;state.route="home";render()}function showStateMenu(){modal.classList.remove("hidden");modal.innerHTML=`<div class="sheet"><h2>Ambiente de teste</h2><div class="menu-list"><button onclick="resetProspect();closeModal()">👋 Ainda não sou cliente</button><button onclick="becomeCustomer()">✈️ Já sou cliente</button><button onclick="openLive()">🔴 Simular modo Live</button><button onclick="openAlbum()">📸 Ver álbum e memórias</button><button onclick="openAdminPreview()">👨‍💼 Prévia do administrador</button><button onclick="closeModal()">Fechar</button></div></div>`}if("serviceWorker" in navigator){window.addEventListener("load",()=>navigator.serviceWorker.register("service-worker.js"))}

function openAdminPreview(){
  modal.classList.remove("hidden");
  modal.innerHTML=`<div class="sheet">
    <h2>👨‍💼 Prévia do Administrador</h2>
    <p>Visual inicial do painel operacional do Indo por Aí.</p>

    <div class="card">
      <h3>Operação de Hoje</h3>
      <p>🚐 3 Transfers</p>
      <p>🍷 2 Experiências</p>
      <p>🏨 4 Check-ins</p>
    </div>

    <div class="card" style="margin-top:14px">
      <h3>Atualizar Cliente</h3>
      <label>Cliente</label>
      <select id="admCliente">
        <option>João Silva</option>
        <option>Ana Costa</option>
      </select>

      <label style="margin-top:10px;display:block">Status</label>
      <select id="admStatus">
        <option>Van solicitada</option>
        <option>Motorista a caminho</option>
        <option>Van chegou</option>
      </select>

      <button class="cta" style="width:100%;margin-top:16px" onclick="simularEnvio()">Enviar atualização</button>
    </div>

    <div id="admResultado"></div>

    <button class="chip" style="width:100%;margin-top:16px" onclick="closeModal()">Fechar</button>
  </div>`;
}

function simularEnvio(){
 const c=document.getElementById("admCliente").value;
 const s=document.getElementById("admStatus").value;
 document.getElementById("admResultado").innerHTML=
 `<div class="notice" style="margin-top:15px">
 ✅ Notificação enviada para <b>${c}</b><br><br>
 🚐 ${s}
 </div>`;
}
